    add_declare(instrument_id='tof_spectrometer', type='double', name='A2'),
    add_declare(instrument_id='tof_spectrometer', type='double', name='A3'),
    add_declare(instrument_id='tof_spectrometer', type='double', name='A2cradle'),
    add_declare(instrument_id='tof_spectrometer', type='int', name='iTOF_CHA_RESOL'),
    add_declare(instrument_id='tof_spectrometer', type='double', name='iELPEAK'),
